// Writes js/quotes.js from design/quotes-en.md and design/quotes-de.md (PRD 3.9).
// Run after editing the quote files: node tools/make-quotes.mjs
import fs from "node:fs";
import { readQuotes, LISTS } from "./quotes-md.mjs";

const design = new URL("../design/", import.meta.url);
const quotes = readQuotes(design);
const body = LISTS.map((list) => `  ${list}: [\n` + quotes[list].map((q) => "    " + JSON.stringify(q)).join(",\n") + "\n  ]").join(",\n");
const src = `// Star Wars quotes for the popups (PRD 3.9), pure.
// GENERATED by tools/make-quotes.mjs from design/quotes-en.md and design/quotes-de.md –
// edit those files and run the tool again (a unit test checks that they match).
// Each entry: { en, de, by: { en, de } | null } (by = speaker of a real film line).

export const QUOTE_LISTS = ${JSON.stringify(LISTS)};

export const QUOTES = {
${body}
};

// Text and speaker of quote \`index\` of \`list\` in \`lang\` (English as fallback).
export function quoteText(list, index, lang) {
  const q = QUOTES[list] && QUOTES[list][index];
  if (!q) return null;
  return { text: q[lang] || q.en, by: q.by ? q.by[lang] || q.by.en : null };
}

// A shuffled deck per list: no quote repeats before its list is used up, and a new
// round never starts with the quote that ended the last one. \`rng\` is a createRng().
export function createQuoteDeck(rng) {
  const decks = {}, last = {};
  return {
    draw(list) {
      const size = QUOTES[list].length;
      if (!decks[list] || decks[list].length === 0) {
        const order = rng.shuffle(Array.from({ length: size }, (_, i) => i));
        if (size > 1 && order[order.length - 1] === last[list]) [order[0], order[order.length - 1]] = [order[order.length - 1], order[0]];
        decks[list] = order;
      }
      last[list] = decks[list].pop();
      return last[list];
    }
  };
}
`;
fs.writeFileSync(new URL("../js/quotes.js", import.meta.url), src);
console.log("js/quotes.js:", LISTS.map((l) => `${l} ${quotes[l].length}`).join(", "));
